/*
 * The page only draws: everything it shows is worked out here, from one answer.
 * The verdict is the newest version's: with Richard (pending), approved, or changes asked.
 */
if (Inputs.list === undefined || Inputs.statuses === undefined) return;
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const statuses = (Inputs.statuses || []).filter((s) => get(s, 'kind') === 'homework')
  .map((s) => ({ value: get(s, 'value'), labelKey: get(s, 'labelKey'), bg: get(s, 'bg'), fg: get(s, 'fg') }));
const statusOf = (v) => statuses.find((s) => s.value === v) || { labelKey: '', bg: 'var(--muted)', fg: 'var(--muted-foreground)' };
let tz = String((Inputs.me && Inputs.me.timezone) || '');
try { new Date().toLocaleString('en-GB', { timeZone: tz || undefined }); } catch (e) { tz = ''; }
const zone = tz || Intl.DateTimeFormat().resolvedOptions().timeZone;
const day = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' });
const at = (iso) => {
  const d = new Date(iso);
  if (!iso || isNaN(d)) return '';
  return day(iso) + ', ' + d.toLocaleTimeString('en-GB', { timeZone: zone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
};
const step = Inputs.step || null;
const list = Array.isArray(Inputs.list) ? Inputs.list : [];
const versions = Array.isArray(Inputs.versions) ? Inputs.versions : [];

Outputs.timezone = zone;
Outputs.showList = !step && list.length > 0;
Outputs.listEmpty = !step && list.length === 0;
Outputs.listRows = list.map((h) => {
  const st = statusOf(h.status);
  return {
    id: h.id, n: String(h.n), title: h.title,
    headKey: h.dueAt ? 'home.hwHead' : 'home.hwHeadNoDue', date: h.dueAt ? day(h.dueAt) : '',
    statusKey: st.labelKey, statusBg: st.bg, statusFg: st.fg
  };
});
Outputs.showOne = !!step;
Outputs.pageTitleKey = step ? 'homework.titleOne' : 'homework.title';
Outputs.pageName = step ? step.title : '';
Outputs.pageLeadKey = step ? '' : 'homework.lead';
if (!step) {
  Outputs.verdictShown = false;
  Outputs.hasVersions = false;
  Outputs.canHandIn = false;
  Outputs.done();
  return;
}
const st = statusOf(step.status);
Outputs.stepId = step.id;
Outputs.headKey = step.dueAt ? 'home.hwHead' : 'home.hwHeadNoDue';
Outputs.n = String(step.n);
Outputs.date = step.dueAt ? day(step.dueAt) : '';
Outputs.title = step.title;
Outputs.statusKey = st.labelKey;
Outputs.statusBg = st.bg;
Outputs.statusFg = st.fg;
Outputs.brief = step.brief || '';
const checklist = (step.handInChecklist || []).map((c, i) => ({ id: step.id + '-item-' + i, text: String((c && c.text) || ''), optional: !!c && c.required === false }));
Outputs.checklist = checklist;
Outputs.hasChecklist = checklist.length > 0;
const resources = (step.resources || []).map((r, i) => ({
  id: step.id + '-res-' + i, label: String((r && r.label) || (r && (r.fileName || r.url)) || ''),
  url: (r && r.url) || '', file: (r && r.file) || '', fileName: (r && r.fileName) || '',
  isFile: !!(r && r.file), isLink: !(r && r.file) && !!(r && r.url), stepId: step.id
}));
Outputs.resources = resources;
Outputs.hasResources = resources.length > 0;
Outputs.canHandIn = step.canHandIn === true;
Outputs.nextVersion = String((versions[0] ? versions[0].version : 0) + 1);
Outputs.versions = versions;
Outputs.hasVersions = versions.length > 0;
const newest = versions[0];
const LOOK = {
  pending: { key: 'homework.verdictPending', bg: 'var(--waiting-bg)', fg: 'var(--foreground)', border: 'var(--border)' },
  approved: { key: 'homework.verdictApproved', bg: 'var(--done-bg)', fg: 'var(--done-fg)', border: 'var(--done-border)' },
  changes: { key: 'homework.verdictChanges', bg: 'var(--homework-bg)', fg: 'var(--homework-fg)', border: 'var(--homework-border)' }
};
const look = newest ? LOOK[newest.review] || LOOK.pending : null;
Outputs.verdictShown = !!look;
if (look) {
  Outputs.verdictKey = look.key;
  Outputs.verdictV = String(newest.version);
  Outputs.verdictWhen = at(newest.review === 'pending' ? newest.handedInAt : newest.reviewedAt);
  Outputs.verdictNote = newest.review === 'pending' ? '' : (newest.reviewNote || '');
  Outputs.verdictHasNote = newest.review !== 'pending' && !!newest.reviewNote;
  Outputs.verdictBg = look.bg;
  Outputs.verdictFg = look.fg;
  Outputs.verdictBorder = look.border;
}
Outputs.done();
